const base = $json;
const content = base._parsed || {};

let needsErrorParse = false;
let errorCode = null;
let errorMessage = null;

const intentionNodesIn = base.intention_nodes || {};
const activeNode = intentionNodesIn[base.active_node_id] || {};
let formState = activeNode.form_state;
let shouldExecute = false;
let activeNodeId = base.active_node_id;
let nodeStatus = activeNode.status;
let resumeTargetId = null;
let resetProcess = false;

if (base._parse_error) {
  needsErrorParse = true;
  errorCode = 'FORM_ERROR';
} else if (content.status === 'in_progress') {
  formState = { ...(formState || {}), ...(content.form_state || {}) };
} else if (content.status === 'confirmed') {
  formState = { ...(formState || {}), ...(content.form_state || {}), ready: true };
  shouldExecute = true;
} else if (content.status === 'cancelled') {
  // User abandoned the form mid-fill (e.g. "never mind, cancel that"). active_node_id
  // moves on below (auto-resume to whatever this interrupted, or null if nothing was),
  // and the node itself is marked 'abandoned' so the Intention Graph reflects that it was
  // deliberately walked away from, instead of silently staying 'active' forever
  // (confirmed-dead gap from before this fix -- nothing ever marked the node itself).
  // form_state is left as whatever was collected so far, not nulled -- an abandoned node
  // keeps a record of what was entered, same as a completed one keeps what was submitted,
  // so the user can copy data from it into a new intention later even though the
  // intention itself is closed.
  nodeStatus = 'abandoned';
  // Auto-resume: this form-filling process interrupted whatever was active before it
  // (Park Current Intent set its own parent_id to that node's id at creation time) -- now
  // that it's abandoned, hand control back rather than stranding active_node_id on null.
  // Same TERMINAL_STATUSES/walk shape duplicated in Park Current Intent
  // (intent-manager.json), Compute Execution Outcome (sap-inquiry-execution.json),
  // Classify & Store Error (error-parser.json), and Resolve Final State
  // (batch-processing.json) -- keep all five in sync if this changes.
  const TERMINAL_STATUSES = new Set(['completed', 'abandoned']);
  const findResumeTarget = (nodeId, nodes) => {
    let current = nodeId;
    while (current) {
      const node = nodes[current];
      if (!node) return null;
      if (!TERMINAL_STATUSES.has(node.status)) return current;
      current = node.parent_id;
    }
    return null;
  };
  resumeTargetId = findResumeTarget(activeNode.parent_id, intentionNodesIn);
  activeNodeId = resumeTargetId;
  // active_node_id must be forced through even when it lands on null (nothing to resume
  // to) -- Django's resettable merge otherwise coalesces an explicit null back to
  // whatever's already in Redis (main.py's _merge_field, resettable=True only lets null
  // through when reset_process is set).
  resetProcess = true;
} else {
  // Anything else (including a stray switch_needed, which Agent: Form's prompt no longer
  // even offers) is unexpected by the time a message reaches this file -- Agent: Intent
  // Finder's own park-before-new-intent check is what's supposed to catch an unrelated
  // request before it ever gets here. Surface it as an error rather than mishandling it.
  needsErrorParse = true;
  errorCode = 'FORM_ERROR';
  errorMessage = content.message || null;
}

// Mirror the freshly computed form_state/status into the node's own saved copy on every
// turn -- intention_nodes[active_node_id] is the only copy that exists, kept current here
// so Prompt: Intention Focus (agent-intent-finder.json) never sees stale progress. Keyed
// off the ORIGINAL active_node_id (not the possibly-just-cleared output value above), a
// no-op via spread if it's ever missing or not found in intention_nodes.
let intentionNodes = base.active_node_id && intentionNodesIn[base.active_node_id]
  ? { ...intentionNodesIn, [base.active_node_id]: { ...activeNode, form_state: formState, status: nodeStatus } }
  : intentionNodesIn;
if (resumeTargetId) {
  intentionNodes = { ...intentionNodes, [resumeTargetId]: { ...intentionNodes[resumeTargetId], status: 'active' } };
}

return [{ json: {
  ...base,
  message: content.message ?? base.message,
  active_node_id: activeNodeId,
  intention_nodes: intentionNodes,
  reset_process: resetProcess,
  _should_execute: shouldExecute,
  _needs_error_parse: needsErrorParse,
  ...(needsErrorParse ? { error: errorCode, error_message: errorMessage } : {}),
} }];

const STATUS = { collecting: { es: 'Recopilando informaci\u00f3n', en: 'Collecting information' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.collecting[lang] } }];

const data = $('Status Text: Collecting').first().json;
const { language, current_date, expertise_level, message, last_bot_message, active_node_id, intention_nodes, focus } = data;
const nodes = intention_nodes || {};
const { process_definition, form_state, parent_id, error_detail } = nodes[active_node_id] || {};
if (!process_definition) {
  return [{ json: { chatInput: `{"status":"cancelled","message":"System error: process definition is missing. Please start over.","form_state":null,"processes":null}` } }];
}
const { output: _o, ...defClean } = process_definition;
const VERBOSITY = {
  1: `Ask PENDING fields one at a time. Include the field description and an example value. Ask ALL fields (required AND optional) — do not skip any optional field; ask each one individually so the user can provide a value or explicitly decline it. When FIELD STATUS shows [CONFIRMATION REQUIRED]: present a formatted summary of ALL collected data, ask the user to approve before submitting, set status to 'in_progress', and add _confirmation_shown:true to form_state. Only set status to 'confirmed' on the turn AFTER the user explicitly says yes/confirm/proceed. This never skips reading the CURRENT USER MESSAGE below for real values -- extract anything it actually gives you first.`,
  2: `Ask 2-3 PENDING fields together (see FIELD STATUS below). Use field labels only, no descriptions. Ask required fields; ask optional pending fields only if contextually relevant. Auto-confirm when all required fields are collected AND every value the CURRENT USER MESSAGE below actually provides -- for any field, required or optional, including every QUERY FILTER if this is a search process -- has been extracted into form_state first.`,
  3: `Batch ALL PENDING required fields in one message (see FIELD STATUS below). Skip descriptions, skip examples. "Skip optional fields" means skip ASKING about ones the user hasn't mentioned -- it never means skip reading the CURRENT USER MESSAGE below. Always extract every value that message actually provides first -- for any field, required or optional, including every QUERY FILTER if this is a search process -- THEN set status to confirmed once all required fields are present.`,
}[expertise_level] || `Ask 2-3 PENDING fields together. Extract every value the CURRENT USER MESSAGE below actually provides first, then auto-confirm.`;
const state = form_state || {};
const isGetQuery = (process_definition?.api?.method || '').toUpperCase() === 'GET';
const SKIP_KEYS = new Set(['ready', 'items_count', 'top', 'skip', 'requested_fields', 'response_format', 'match_all', '_extra_fields', '_confirmation_shown']);
const filledLines = [];
const declinedLines = [];
const pendingLines = [];
for (const section of (process_definition?.form?.sections || [])) {
  if (section.multiple) {
    const items = state[section.id];
    const requiredFields = (section.fields || []).filter(f => f.required).map(f => f.id);
    const allFieldIds = (section.fields || []).map(f => f.id);
    const hasItems = Array.isArray(items) && items.length > 0;
    const isItemComplete = (item) => {
      if (expertise_level === 1) {
        // Guided: ALL defined fields must be explicitly present (null = declined, value = filled)
        return allFieldIds.every(fid => fid in item);
      }
      if (requiredFields.length > 0) {
        return requiredFields.every(fid => item[fid] !== null && item[fid] !== undefined && String(item[fid]).trim() !== '');
      }
      return Object.values(item).some(v => v !== null && v !== undefined && String(v).trim() !== '');
    };
    const completeCount = hasItems ? items.filter(isItemComplete).length : 0;
    const allComplete = hasItems && completeCount === items.length;
    const sectionRequired = section.required !== false;
    const completionLabel = expertise_level === 1 ? 'all fields' : 'all required fields';
    if (!hasItems || !allComplete) {
      const started = hasItems ? items.length : 0;
      pendingLines.push(`  [PENDING] ${section.id} (${section.label}, ${sectionRequired ? 'REQUIRED' : 'optional'} — ${started} item(s) started, ${completeCount}/${started} have ${completionLabel} filled)`);
    } else {
      filledLines.push(`  [FILLED] ${section.id} (${section.label}) — ${items.length} item(s), ${completionLabel} complete`);
    }
  } else {
    for (const field of (section.fields || [])) {
      if (SKIP_KEYS.has(field.id)) continue;
      if (field.id in state) {
        if (state[field.id] === null) {
          declinedLines.push(`  [DECLINED] ${field.id} (${field.label})`);
        } else {
          filledLines.push(`  [FILLED] ${field.id} (${field.label}) = ${JSON.stringify(state[field.id])}`);
        }
      } else {
        pendingLines.push(`  [PENDING] ${field.id} (${field.label}${field.required ? ', REQUIRED' : ', optional'})`);
      }
    }
  }
}
let completionStatus;
if (pendingLines.length === 0) {
  if (expertise_level === 1 && !isGetQuery && !state._confirmation_shown) {
    completionStatus = `  [CONFIRMATION REQUIRED] All fields collected. Present a formatted summary of all data (every FILLED and DECLINED field, and each line item with all its fields), ask the user to confirm before submitting, return status='in_progress', and include _confirmation_shown:true in form_state. Do NOT return status='confirmed' on this turn.`;
  } else {
    completionStatus = (isGetQuery && Array.isArray(process_definition?.query?.filters) && process_definition.query.filters.length > 0)
      ? `  (no required form.sections fields -- this is a search/query process; see QUERY FILTERS below and check the CURRENT USER MESSAGE for filter values before deciding to confirm)`
      : `  (all fields complete — ready to confirm)`;
  }
} else {
  completionStatus = pendingLines.join('\n');
}
const fieldStatus = [
  `## FIELD STATUS — AUTHORITATIVE (computed by code, not by LLM; overrides all other reasoning)`,
  `FILLED — already collected; don't ask about these again unprompted. But nothing here has been submitted to SAP yet, so if the user's message provides a new value for one — including a value inherited from an earlier failed attempt at this same request — treat it as a correction and update it. Only an entity already created in SAP needs its own separate update process; anything still in this form is freely editable at any time:`,
  filledLines.length ? filledLines.join('\n') : `  (none)`,
  `DECLINED by user — user said no, do NOT ask again:`,
  declinedLines.length ? declinedLines.join('\n') : `  (none)`,
  `PENDING — not yet complete, must be collected before confirming:`,
  completionStatus,
].join('\n');

// FIELD STATUS above only ever tracks process_definition.form.sections (the POST_CREATE
// shape) -- a GET-type process has query.filters instead, which that loop never sees at
// all. Left alone, FIELD STATUS would say "all fields complete" for every GET query
// unconditionally, on every single turn, which reads as a strong "nothing left to do"
// signal even when the user's own message just gave real filter values. This section is
// query.filters' own dedicated status block, computed the same deterministic way, so a GET
// process gets equally prominent, structured field-by-field context instead of relying on
// the model noticing filter values buried in a large raw PROCESS DEFINITION JSON blob.
let queryFiltersSection = '';
if (isGetQuery && Array.isArray(process_definition?.query?.filters) && process_definition.query.filters.length > 0) {
  const filterLines = process_definition.query.filters.map((f) => {
    const val = state[f.id];
    const allowedOps = Array.isArray(f.operator) ? f.operator : [f.operator];
    if (val !== null && val !== undefined) {
      const chosenOp = state[`${f.id}_operator`];
      return `  [SET] ${f.id} (${f.label}) = ${JSON.stringify(val)}${chosenOp ? ` [operator: ${chosenOp}]` : ''}`;
    }
    const opsNote = allowedOps.length > 1
      ? ` — allowed operators: ${allowedOps.join(', ')}; if you extract a value, also store form_state.${f.id}_operator with the one that matches the user's phrasing`
      : '';
    return `  [AVAILABLE] ${f.id} (${f.label}, ${f.type})${opsNote}`;
  });
  queryFiltersSection = `\n\n## QUERY FILTERS FOR THIS SEARCH (GET-type process — NOT covered by FIELD STATUS above, which only tracks form.sections. Re-check the CURRENT USER MESSAGE below against every filter listed here, every turn, even when FIELD STATUS says nothing is pending — an [AVAILABLE] filter is not "nothing to extract", it's "check the message for this"):\n${filterLines.join('\n')}`;
}

const focusBlock = focus
  ? `\n\n## USER'S CURRENT FOCUS (from Agent: Intention Focus -- grounding context, not a directive; use it to judge whether the CURRENT MESSAGE continues/repeats this same search or is a fresh, different one)\n${focus}`
  : '';
const parentNode = (isGetQuery && parent_id) ? nodes[parent_id] : null;
const parentIsSameQuery = parentNode && parentNode.process_id === process_definition?.id;
let previousFiltersBlock = '';
if (parentIsSameQuery && parentNode.form_state && Object.keys(parentNode.form_state).length) {
  const parentTop = parentNode.form_state.top || process_definition?.query?.top || 20;
  const parentSkip = parentNode.form_state.skip || 0;
  const suggestedNextSkip = parentSkip + parentTop;
  previousFiltersBlock = `\n\n## PREVIOUS FILTERS FROM THE PRIOR TURN OF THIS SAME QUERY (reuse these ONLY if FOCUS above or the CURRENT MESSAGE indicates this is a continuation -- e.g. "same filter", "con el mismo filtro", "next page", "más resultados". If the CURRENT MESSAGE instead specifies a fresh/different set of filters, or explicitly asks for an unfiltered list, ignore this block entirely and build form_state from the CURRENT MESSAGE alone):\n${JSON.stringify(parentNode.form_state, null, 2)}\n\nIf this turn is a "next page" / "more results" request, the correct new form_state.skip is ${suggestedNextSkip} (precomputed: previous skip ${parentSkip} + previous top ${parentTop} -- copy this value verbatim, do not calculate your own).`;
}
const lastMessageContext = last_bot_message || '(none — first message in this form)';
// Read side of the error_detail fix (write side: sap-inquiry-execution.json's Compute
// Execution Outcome, on the SAP-rejected branch) -- without this, resuming a node that
// previously failed gives the agent no way to answer "what went wrong", even though the
// node's own error_detail already carries the exact SAP rejection reason.
const errorDetailBlock = error_detail
  ? `\n\n## PREVIOUS ATTEMPT FAILED (SAP rejected the last submission of this same request -- if the user asks what went wrong or why they are correcting this, cite this verbatim; it will not recur once the offending field is fixed and resubmitted)\n${error_detail}`
  : '';
const chatInput = `Today: ${current_date}. Respond in: ${language}.

## INTERACTION STYLE
${VERBOSITY}

## STATUS REPORTING (optional)
If this turn is likely to take a noticeable moment (e.g. reasoning through many pending fields, or an unusually large PROCESS DEFINITION below), you may call the send_status tool ONCE with group_name="${data.group_name}", session_id=${data.session_id}, and a short human-readable message in ${language} (e.g. "Revisando los campos..."). This is purely supplementary narration shown in place of the typing indicator -- it never replaces the OUTPUT below, which you must always still return.

${fieldStatus}

## PROCESS DEFINITION
${JSON.stringify(defClean, null, 2)}

## CURRENT FORM STATE
${JSON.stringify(state, null, 2)}

## LAST MESSAGE YOU SENT (context only, to ground a terse or batched reply — FIELD STATUS above is still authoritative for what's filled/pending)
${lastMessageContext}${errorDetailBlock}${queryFiltersSection}${focusBlock}${previousFiltersBlock}

## USER MESSAGE -- READ THIS CAREFULLY AGAINST QUERY FILTERS ABOVE (if any) BEFORE DECIDING YOUR RESPONSE
"${message}"

## READ-ONLY REQUESTS OVERRIDE AUTO-CONFIRM
If the USER MESSAGE above is only asking to see, review, recap, or double-check the current data (e.g. "show me the details", "mostrame el detalle", "what do we have so far") — and is not itself providing a new value, correcting a field, or explicitly saying yes/confirm/proceed — answer it directly by presenting the current field values, return status='in_progress', and do NOT advance to 'confirmed' even if every field above is already filled. Only move to 'confirmed' when the user's own message provides data that completes the form or explicitly confirms submission.

## OUTPUT
In progress: {"status": "in_progress", "message": "<question in ${language}>", "form_state": {...updated...}, "processes": null}
All required fields collected: {"status": "confirmed", "message": "<brief in ${language}>", "form_state": {...complete...}, "processes": null}
Cancelled: {"status": "cancelled", "message": "<in ${language}>", "form_state": null, "processes": null}`;
return [{ json: { ...data, chatInput } }];
